// Writes src/lib/manifest.generated.ts from .product-team/environment-manifest.yml (#102), so the Worker and the
// console read the one manifest without a YAML parser at run time. Rerun after every manifest change:
//   node libs/shared/environment/scripts/generate-manifest.mjs
// src/lib/manifest.spec.ts fails until the generated file matches the manifest again.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '../../../..');
const manifest = parse(readFileSync(join(root, '.product-team/environment-manifest.yml'), 'utf8'));

const source = `// Generated by libs/shared/environment/scripts/generate-manifest.mjs from .product-team/environment-manifest.yml.
// Do not edit by hand: change the manifest and rerun the script (manifest.spec.ts keeps the two equal).
import type { EnvironmentManifest } from './manifest';

export const ENVIRONMENT_MANIFEST: EnvironmentManifest = ${JSON.stringify(manifest, null, 2)};
`;

writeFileSync(join(here, '../src/lib/manifest.generated.ts'), source);
